import numpy as np
def equation(eps, T, params):
    a,b,q,c,d,k,p,g,h,s=params[:10]
    x=np.exp(-q*T)
    E=np.exp(-k*eps*T**p)
    return a+b*x+c*eps+(d+s*x)*eps*E+g*x*E+h*eps**2*np.exp(-s*T)
